using SimplePZMapmaker.Core;
public static class WalkabilityTests {
 public static IEnumerable<(string,Action)> Cases(){
  yield return ("a completely blocked room does not disappear from access diagnostics",()=>{var b=House();var f=b.Design!.Floors[0];f.Objects.Clear();foreach(var e in f.Edges.Where(e=>e.Kind=="door"))e.Kind="wall";for(var y=0;y<b.Height;y++)for(var x=0;x<b.Width;x++)f.Objects.Add(new(){X=x,Y=y,Kind="asset",Parts=[new(0,0,"fixture",1)]});Check(WalkabilityAnalyzer.Building(b).Issues.Any(i=>i.Code=="blocked-room"&&i.Severity=="error"),"Fully occupied floor was reported clear");});
  yield return ("installed directional fence properties block pedestrian routes without changing legacy parts",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});for(var x=0;x<16;x++)p.Decorations.Add(new(){X=x,Y=8,Asset="fixture",Parts=[new(0,0,"fixture",0)]});var options=new WalkabilityOptions{Width=16,Height=16,Start=new(4,4,0),End=new(4,12,0)};Check(WalkabilityAnalyzer.Analyze(p,options).Path.Count>0,"Control route missing");var report=WalkabilityAnalyzer.Analyze(p,options,properties:_=>new Dictionary<string,string>{{"HoppableN",""}});Check(report.Path.Count==0&&report.Notes.Any(n=>n.Contains("No pedestrian route")),"Native hoppable fence ignored by walking graph");Check(p.Decorations.All(d=>d.Parts[0].Flags==0),"Analysis rewrote canonical saved parts");
  });
  yield return ("native infrastructure stairs connect the real landings on upper and basement floors",()=>{foreach(var z in new[]{2,-2}){var p=MapGenerator.Generate(new(){Kind="blank"});p=LinearFeatureEditor.Put(p,new(){Id="diagnostic-stairs",Kind="bridge",Width=6,Level=z,Access="stairs",Points=[new(80,100),new(120,100)]});var ground=new WalkPoint(80,100+4*z,0);var end=new WalkPoint(110,100,z);var r=WalkabilityAnalyzer.Analyze(p,new(){X=64,Y=80,Width=80,Height=48,Start=ground,End=end});Check(r.Path.Count>0&&r.Path[0]==ground&&r.Path[^1]==end&&r.Path.Any(c=>c.Z==z/2)&&r.Issues.All(i=>i.Code!="broken-stair"),"Native signed stair landings did not connect");p.Decorations.Add(new(){X=ground.X,Y=ground.Y,Asset="furniture_storage_01_0",Parts=[new(0,0,"furniture_storage_01_0",1)]});r=WalkabilityAnalyzer.Analyze(p,new(){X=64,Y=80,Width=80,Height=48,Start=ground,End=end});Check(r.Path.Count==0&&r.Issues.Any(i=>i.Code=="broken-stair"),"Blocked ground landing accepted");}});
  yield return ("infrastructure entirely outside an analysis crop does not make the crop incomplete",()=>{var p=LinearFeatureEditor.Put(MapGenerator.Generate(new(){Kind="blank"}),new(){Kind="bridge",Level=2,Access="stairs",Points=[new(80,100),new(120,100)]});var r=WalkabilityAnalyzer.Analyze(p,new(){X=0,Y=0,Width=32,Height=32,Start=new(1,10,0),End=new(20,10,0)});Check(r.Complete&&r.Path.Count==20&&!r.Notes.Any(n=>n.Contains("stair transition")),"Unrelated stairs made the crop incomplete");});
  yield return ("shared stair runs clipped at a world section seam report partial coverage on both sides",()=>{var a=MapGenerator.Generate(new(){Kind="blank"});a.WorldX=a.WorldY=0;var b=MapGenerator.Generate(new(){Kind="blank"});b.WorldX=0;b.WorldY=1;var w=WorldInfrastructure.Put(new(){Maps=[new(){Project=a},new(){Project=b}]},new(){Kind="bridge",Level=2,Access="stairs",Points=[new(100,250),new(100,290)]});foreach(var (index,y) in new[]{(0,224),(1,0)}){var r=WalkabilityAnalyzer.World(w,w.Maps[index].Id,new(){X=80,Y=y,Width=48,Height=32});Check(!r.Complete&&r.Notes.Any(n=>n.Contains("stair")),"Clipped world stair claimed complete coverage");Check(r.Coverage.Y==y&&r.Coverage.Height==32,"World section crop coordinates changed");}});
  yield return ("shared ground road has a direct pedestrian route under a separate native bridge floor",()=>{var a=MapGenerator.Generate(new(){Kind="blank"});a.WorldX=a.WorldY=0;var b=MapGenerator.Generate(new(){Kind="blank"});b.WorldX=1;b.WorldY=0;var w=WorldInfrastructure.Put(new(){Maps=[new(){Project=a},new(){Project=b}]},new(){Kind="bridge",Level=2,Width=6,SupportSpacing=12,Points=[new(220,100),new(290,100)]});w=WorldInfrastructure.Put(w,new(){Width=8,Points=[new(228,70),new(228,130)]});var r=WalkabilityAnalyzer.World(w,w.Maps[0].Id,new(){X=208,Y=64,Width=48,Height=80,Start=new(228,80,0),End=new(228,120,0)});Check(r.Path.Count==41&&r.Path.All(c=>c.X==228&&c.Z==0),"A bridge pier or floor blocked the ground road");});
  yield return ("access diagnostics locate sealed rooms without changing the draft",()=>{
   var b=House();b.Design!.Floors[0].Edges=BuildingDesigner.AutoEdges(b,b.Design.Floors[0],0);foreach(var e in b.Design.Floors[0].Edges.Where(e=>e.Kind=="door"))e.Kind="wall";
   var before=System.Text.Json.JsonSerializer.Serialize(b);var r=WalkabilityAnalyzer.Building(b);Check(r.Issues.Any(i=>i.Code=="unreachable-room"&&i.BuildingId==b.Id&&i.Z==0),"Sealed house was reported accessible");Check(before==System.Text.Json.JsonSerializer.Serialize(b),"Diagnostics changed the draft");
  });
  yield return ("access respects full furniture footprints and locked model edges",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});var b=House();p.Buildings.Add(b);var f=b.Design!.Floors[0];var door=f.Edges.First(e=>e.Kind=="door"&&e.Y==0);f.Objects.Add(new(){Kind="asset",X=door.X-1,Y=0,Parts=[new(0,0,"furniture_storage_01_0",1),new(1,0,"furniture_storage_01_0",1)]});
   var r=WalkabilityAnalyzer.Analyze(p,new(){X=0,Y=0,Width=40,Height=40});Check(r.Issues.Any(i=>i.Code=="blocked-opening"),"Second furniture tile was ignored");
   f.Objects.Clear();f.StaticModels.Add(new(){ModelId="Base.Test",Profile="door",X=door.X,Y=door.Y,Door=new(){Locked=true,Direction=door.Edge}});r=WalkabilityAnalyzer.Analyze(p,new(){X=0,Y=0,Width=40,Height=40});Check(r.Issues.Any(i=>i.Code=="unreachable-room"),"Locked door treated as open");
  });
  yield return ("access checks actual upper anchor and lower stair landing",()=>{
   var b=House(2);var stair=b.Design!.Floors[0].Objects.Single(o=>o.Kind=="stairs");var upper=b.Design.Floors[1];var cells=upper.Cells.ToCharArray();cells[stair.Y*b.Width+stair.X]='.';upper.Cells=new(cells);var r=WalkabilityAnalyzer.Building(b);Check(r.Issues.Any(i=>i.Code=="broken-stair"&&i.Z==0),"Missing upper anchor accepted");
  });
  yield return ("access coverage and path endpoints are explicit",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});p.Terrain[10*p.Width+10]=Terrain.Water;var r=WalkabilityAnalyzer.Analyze(p,new(){X=0,Y=0,Width=32,Height=32,Start=new(9,10,0),End=new(11,10,0)});Check(r.Path.Count>3&&r.Path.All(c=>c.X!=10||c.Y!=10),"Path crossed water");
   r=WalkabilityAnalyzer.Analyze(p,new(){X=0,Y=0,Width=32,Height=32,MaximumNodes=64});Check(!r.Complete&&r.Notes.Any(n=>n.Contains("budget")),"Truncated graph claimed complete coverage");
   var b=House();p.Buildings.Add(b);r=WalkabilityAnalyzer.Analyze(p,new(){X=b.X+2,Y=b.Y,Width=8,Height=8});Check(!r.Complete&&r.Issues.All(i=>i.Code!="unreachable-room"),"Cropped building produced false unreachable result");
  });
  yield return ("upper open edges are reported and guarded walls are safe",()=>{
   var b=House(2);b.Design!.Floors[0].Objects.Clear();var f=b.Design.Floors[1];f.Edges.Clear();var r=WalkabilityAnalyzer.Building(b);Check(r.Issues.Any(i=>i.Code=="unsafe-edge"&&i.Z==1),"Open balcony edge hidden");f.Edges=BuildingDesigner.AutoEdges(b,f,1);r=WalkabilityAnalyzer.Building(b);Check(r.Issues.All(i=>i.Code!="unsafe-edge"),"Guarded facade treated as open edge");
  });
 }
 static Building House(int floors=1){var b=new Building{X=8,Y=8,Width=12,Height=10};b.Design=BuildingDesigner.Generate(b,floors,42,"rect");foreach(var f in b.Design.Floors)f.Objects.RemoveAll(o=>o.Kind!="stairs");return b;}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
}
